# Generated by manage.py generate_test_cases.
from django.contrib.contenttypes.models import ContentType

from bloomerp.models import ApplicationField
from bloomerp.models.forms.form import Form
from bloomerp.models.users.user_object_layout_preference import (
    UserObjectLayoutPreference,
)
from bloomerp.models.workspaces.tile import Tile
from bloomerp.models.workspaces.workspace import Workspace
from bloomerp.permissions.definition import BloomerpPermission
from bloomerp.permissions.manager import PolicyManager
from bloomerp.tests.base import (
    BloomerpComponentTestCase,
    ExpectedResult,
    RequestScenario,
)


class TestAvailableLayoutItemsComponent(BloomerpComponentTestCase):
    """Tests function `available_layout_items` from `bloomerp/components/layout/available_layout_items.py`."""

    view_name = "components_available_layout_items"

    def setUp(self) -> None:
        super().setUp()
        self.customer_content_type = ContentType.objects.get_for_model(
            self.CustomerModel
        )
        self.form_content_type = ContentType.objects.get_for_model(Form)
        self.object_layout_content_type = ContentType.objects.get_for_model(
            UserObjectLayoutPreference
        )
        self.workspace_content_type = ContentType.objects.get_for_model(Workspace)
        self.first_name_field = ApplicationField.get_by_field(
            self.CustomerModel,
            "first_name",
        )
        self.admin_tile = Tile.objects.create(
            name="Admin-only tile",
            type="ANALYTICS_TILE",
            schema={},
            created_by=self.admin_user,
            updated_by=self.admin_user,
        )

    def get_test_scenarios(self) -> list[RequestScenario]:
        target_query = {"target_content_type_id": self.customer_content_type.pk}

        return [
            RequestScenario(
                name="admin can list fields for a form layout",
                user=self.admin_user,
                view_kwargs={"content_type_id": self.form_content_type.pk},
                query_params=target_query,
                expected=ExpectedResult(
                    response_validators=lambda response: any(
                        str(item["id"]) == str(self.first_name_field.pk)
                        for item in response.context["items"]
                    ),
                ),
            ),
            RequestScenario(
                name="admin can list fields for an object layout",
                user=self.admin_user,
                view_kwargs={
                    "content_type_id": self.object_layout_content_type.pk
                },
                query_params={**target_query, "layout_mode": "detail"},
                expected=ExpectedResult(
                    response_validators=lambda response: any(
                        str(item["id"]) == str(self.first_name_field.pk)
                        for item in response.context["items"]
                    ),
                ),
            ),
            RequestScenario(
                name="admin can list workspace tiles",
                user=self.admin_user,
                view_kwargs={"content_type_id": self.workspace_content_type.pk},
                expected=ExpectedResult(
                    response_validators=lambda response: any(
                        item.id == self.admin_tile.pk
                        for item in response.context["items"]
                    ),
                ),
            ),
            RequestScenario(
                name="normal user without add permission cannot list form fields",
                user=self.normal_user,
                view_kwargs={"content_type_id": self.form_content_type.pk},
                query_params=target_query,
                expected=ExpectedResult(status_code=403),
            ),
            RequestScenario(
                name="normal user without view permission cannot list object fields",
                user=self.normal_user,
                view_kwargs={
                    "content_type_id": self.object_layout_content_type.pk
                },
                query_params={**target_query, "layout_mode": "detail"},
                expected=ExpectedResult(status_code=403),
            ),
            RequestScenario(
                name="normal user cannot list another user's workspace tile",
                user=self.normal_user,
                view_kwargs={"content_type_id": self.workspace_content_type.pk},
                expected=ExpectedResult(
                    response_validators=lambda response: all(
                        item.id != self.admin_tile.pk
                        for item in response.context["items"]
                    ),
                ),
            ),
            RequestScenario(
                name="normal user with add permission can list form fields",
                user=self.normal_user,
                view_kwargs={"content_type_id": self.form_content_type.pk},
                query_params=target_query,
                prepare=lambda _scenario: self._grant_customer_field_permission(
                    BloomerpPermission.ADD
                ),
                expected=ExpectedResult(
                    response_validators=lambda response: [
                        str(item["id"]) for item in response.context["items"]
                    ]
                    == [str(self.first_name_field.pk)],
                ),
            ),
            RequestScenario(
                name="normal user with view permission can list object fields",
                user=self.normal_user,
                view_kwargs={
                    "content_type_id": self.object_layout_content_type.pk
                },
                query_params={**target_query, "layout_mode": "detail"},
                prepare=lambda _scenario: self._grant_customer_field_permission(
                    BloomerpPermission.VIEW
                ),
                expected=ExpectedResult(
                    response_validators=lambda response: [
                        str(item["id"]) for item in response.context["items"]
                    ]
                    == [str(self.first_name_field.pk)],
                ),
            ),
            RequestScenario(
                name="normal user can list their own workspace tile",
                user=self.normal_user,
                view_kwargs={"content_type_id": self.workspace_content_type.pk},
                prepare=lambda _scenario: self._create_normal_user_tile(),
                expected=ExpectedResult(
                    response_validators=lambda response: any(
                        item.id == self.normal_user_tile.pk
                        for item in response.context["items"]
                    ),
                ),
            ),
        ]

    def _grant_customer_field_permission(
        self,
        permission: BloomerpPermission,
    ) -> None:
        PolicyManager.create_policy(
            self.CustomerModel,
            field_permissions={self.first_name_field: [permission]},
            row_permissions=[],
            global_permissions=[permission],
        ).assign_user(self.normal_user)

    def _create_normal_user_tile(self) -> None:
        self.normal_user_tile = Tile.objects.create(
            name="Normal user's tile",
            type="ANALYTICS_TILE",
            schema={},
            created_by=self.normal_user,
            updated_by=self.normal_user,
        )
